/**
 * @summary List salary benchmark data
 */
export const getListBenchmarksUrl = (params?: ListBenchmarksParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/benchmark?${stringifiedParams}`
    : `/api/benchmark`;
};

export const listBenchmarks = async (
  params?: ListBenchmarksParams,
  options?: RequestInit,
): Promise<SalaryBenchmark[]> => {
  return customFetch<SalaryBenchmark[]>(getListBenchmarksUrl(params), {
    ...options,
    method: "GET",
  });
};

